SELECT id, product_id, quantity, NTILE(5) OVER (PARTITION BY product_id ORDER BY quantity DESC, id ASC) AS quantity_bucket, AVG(quantity) OVER (PARTITION BY product_id, store_id) AS product_id_avg_quantity, RANK() OVER w_hist AS quantity_rank, LAG(quantity, 2) OVER w_recent AS prev_quantity FROM inventory WHERE store_id IN (1, 3, 5) WINDOW w_hist AS (ORDER BY quantity DESC NULLS LAST), w_recent AS (PARTITION BY store_id ORDER BY last_restock ASC, id ASC);
